FUNCTION_BLOCK FB_S06
VAR_INPUT
    TempPV : REAL;
    SetTemp : REAL;
    Segment : INT;
    LoadReduceReq : BOOL;
END_VAR
VAR_OUTPUT
    HeatOn : BOOL := FALSE;
    FanOn : BOOL := FALSE;
    OverTempAlarm : BOOL := FALSE;
    LoadReduce : BOOL := FALSE;
    Status : WORD := WORD#16#0000;
END_VAR
VAR
    StartupScans : INT := 0;
    TargetTemp : REAL := 0.0;
    InvalidSegment : BOOL := FALSE;
    InvalidSegmentPrev : BOOL := FALSE;
    AutoReduce : BOOL := FALSE;
    HeatDemand : BOOL := FALSE;
END_VAR

(*
    需求冲突保留并报告，待审：
    1. 原文要求超温先降载而不是直接断电；C1/C4 却要求降载时
       HeatOn 必须关断。接口没有降载完成反馈或功率调节输出，
       无法表达并验证分阶段降载。本实现按保护互斥关断加热，
       不声称满足“先降载而不是直接断电”的时序要求。
    2. 原文报警/降载回落阈值基于分段目标，C7 报警保持条件
       却基于 SetTemp 且使用 <=。自动降载按原文严格 < 释放；
       报警仅在两个释放条件均满足时释放，作为待审保守处理。
    3. 原文非法段号当周期报错，C8 要求下一周期报错。
       本实现当周期报错并延续到下一周期，错误码优先于超温码。
    4. C10 的 G[0,1] 按第 0、1 两次调用均关断输出处理；
       这会暂时覆盖启动期间温控、超温和上位机降载请求。
    5. FanOn 在逻辑中先于 HeatOn 赋值，满足 C2 输出联锁；
       无风机反馈，不能证明物理风机已经运行后才加热。

    每次调用为 20 ms。未声称经过编译或逐周期功能验证。
*)

InvalidSegment := (Segment < 0) OR (Segment > 2);

CASE Segment OF
    0:
        TargetTemp := SetTemp * 0.5;
    1:
        TargetTemp := SetTemp * 0.8;
    2:
        TargetTemp := SetTemp;
ELSE
    TargetTemp := SetTemp * 0.5;
END_CASE;

IF StartupScans < 2 THEN
    StartupScans := StartupScans + 1;

    HeatDemand := FALSE;
    AutoReduce := FALSE;
    HeatOn := FALSE;
    FanOn := FALSE;
    OverTempAlarm := FALSE;
    LoadReduce := FALSE;
ELSE
    (* 自动降载：严格超过 +10 置位，严格低于 -3 释放。 *)
    IF TempPV > (TargetTemp + 10.0) THEN
        AutoReduce := TRUE;
    ELSIF TempPV < (TargetTemp - 3.0) THEN
        AutoReduce := FALSE;
    END_IF;

    (* 报警保持，同时保留原文及 C7 的回落条件。 *)
    IF TempPV > (TargetTemp + 10.0) THEN
        OverTempAlarm := TRUE;
    ELSIF (TempPV < (TargetTemp - 3.0))
        AND (TempPV <= (SetTemp - 3.0)) THEN
        OverTempAlarm := FALSE;
    END_IF;

    (* 自动降载与外部请求独立；请求有效期间不撤销降载。 *)
    LoadReduce := AutoReduce OR LoadReduceReq;

    (* 死区内保持实际加热状态；保护动作清除加热保持状态。 *)
    IF LoadReduce THEN
        HeatDemand := FALSE;
    ELSIF TempPV < (TargetTemp - 5.0) THEN
        HeatDemand := TRUE;
    ELSIF TempPV > (TargetTemp + 5.0) THEN
        HeatDemand := FALSE;
    END_IF;

    (* 同一扫描内先更新风机命令，再更新加热命令。 *)
    FanOn := HeatDemand AND NOT LoadReduce;
    HeatOn := HeatDemand AND FanOn AND NOT LoadReduce;
END_IF;

IF InvalidSegment OR InvalidSegmentPrev THEN
    Status := WORD#16#8601;
ELSIF AutoReduce OR OverTempAlarm THEN
    Status := WORD#16#8602;
ELSE
    Status := WORD#16#0000;
END_IF;

InvalidSegmentPrev := InvalidSegment;

END_FUNCTION_BLOCK
